fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Parent indices go from 0 to (n/2) - 1
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check left child
        if left < n && a[left] < a[i] {
            return false;
        }
        // Check right child
        if right < n && a[right] < a[i] {
            return false;
        }
    }
    true
}